      <div class="flex gap-2">
        <input type="password" id="apiKeyInput" class="flex-1 px-3 py-2 border border-blue-200 rounded-lg text-sm" placeholder="AIzaSy...">
        <button onclick="saveApiKey()" class="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold active:bg-blue-700 touch-manipulation">儲存</button>
