        </button>
      </div>
      <div class="relative w-full h-56 bg-gray-200 flex items-center justify-center overflow-hidden">
        <img id="previewImg" src="" alt="請點擊上方按鈕開始拍照" class="object-cover w-full h-full hidden" />
