    <h2 class="text-lg font-bold text-gray-800 mb-3 px-1">AI 辨識結果</h2>
    <!-- 辨識結果會生在這裡 -->
    <div id="resultsContainer" class="space-y-4">
      <div class="border-2 border-dashed border-gray-300 rounded-xl p-8 text-center text-gray-400 text-sm">
