    async function analyzeWithGemini(base64Data, apiKey) {
      const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${apiKey}`;

      const payload = {
        contents: [{
          parts: [
            { text: "這是一張冷凍空調材料的現場盤點照片。請辨識畫面中有哪些材料（如銅管、冷媒桶、保溫棉等）並估算數量。請務必只回傳純 JSON 陣列格式，不要任何 Markdown 標記，格式為：[{\"name\": \"材料名稱\", \"count\": 數量}]。如果看不清楚請回傳空陣列 []。" },
