      document.getElementById('placeholderText').classList.add('hidden');
      document.getElementById('previewImg').classList.remove('hidden');
      document.getElementById('loadingStatus').classList.remove('hidden');
      document.getElementById('loadingText').innerText = 'AI 視覺比對中...';
      document.getElementById('errorMessage').classList.add('hidden');

      try {
        const base64Image = await compressImageAndGetBase64(file);
        document.getElementById('previewImg').src = 'data:image/jpeg;base64,' + base64Image;
        const results = await analyzeWithGemini(base64Image, apiKey);
        renderResults(results);
      } catch (error) {
        showError(`發生錯誤：\n${error.message}`);
