            if ((response.status === 503 || response.status === 429 || errorMsg.toLowerCase().includes("high demand")) && attempt < MAX_RETRIES) {
              // 更新畫面文字，讓你知道它正在努力重試
              document.getElementById('loadingText').innerText = `伺服器壅塞，自動重試中 (${attempt}/${MAX_RETRIES})...`;
              // 暫停 2.5 秒後再發送一次請求
              await new Promise(resolve => setTimeout(resolve, 2500));
              continue; 
            }
            throw new Error(errorMsg || "API 錯誤");
          }

          let aiText = data.candidates[0].content.parts[0].text.replace(/```json/g, '').replace(/```/g, '').trim();
          return JSON.parse(aiText);

        } catch (error) {
          if (attempt === MAX_RETRIES) {
            throw error;
          }
        }
      }
    }

